import (
	"fmt"
)

resp, err := client.Transactions().ListTransactions(ctx, map[string]any{"limit": 50, "offset": 0}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["transactions"].([]any) {
	transaction := row.(map[string]any)
	fmt.Println(transaction["transaction_no"], transaction["total_records"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

